import assert from 'node:assert/strict';
import {readFileSync,readdirSync,existsSync,globSync} from 'node:fs';
import {join,dirname,resolve,relative} from 'node:path';
import ts from 'typescript';
export function files(root:string,directory:string):string[]{const out:string[]=[];function walk(path:string){for(const e of readdirSync(path,{withFileTypes:true})){const p=join(path,e.name);assert.equal(e.isSymbolicLink(),false,'No hidden source alias: '+p);if(e.isDirectory())walk(p);else out.push(relative(root,p));}}if(existsSync(join(root,directory)))walk(join(root,directory));return out.sort();}
export function documentation(root:string,packed:Set<string>){
 const visible=(path:string)=>{let fenced=false,marker='';return readFileSync(join(root,path),'utf8').split('\n').filter(line=>{const m=/^\s*(`{3,}|~{3,})/.exec(line);if(m){if(!fenced){fenced=true;marker=m[1]![0]!;}else if(m[1]![0]===marker)fenced=false;return false;}return !fenced;}).join('\n');};
 const anchors=(path:string)=>{const out=new Set<string>();for(const m of visible(path).matchAll(/^\s{0,3}#{1,6}\s+(.+?)\s*#*\s*$/gm)){const base=m[1]!.replace(/<[^>]*>/g,'').replace(/[`*_~]/g,'').toLowerCase().replace(/[^\p{L}\p{N}\s_-]/gu,'').replace(/\s/g,'-');let id=base,n=0;while(out.has(id))id=base+'-'+(++n);out.add(id);}return out;};
 let links=0;for(const path of packed)if(path.endsWith('.md')){const text=visible(path),targets=[...text.matchAll(/!?\[[^\]\n]*\]\(([^)\s]+)(?:\s+"[^"]*")?\)/g),...text.matchAll(/^\s*\[[^\]\n]+\]:\s*(\S+)/gm)];for(const m of targets){const ref=m[1]!.replace(/^<|>$/g,'');if(/^[a-z][a-z0-9+.-]*:/i.test(ref)||ref.startsWith('//'))continue;const [file='',fragment]=ref.split('#'),target=file?relative(root,resolve(dirname(join(root,path)),decodeURIComponent(file.split('?')[0]!))):path;assert.ok(packed.has(target),'Unshipped/broken Markdown target '+path+' -> '+ref);assert.ok(existsSync(join(root,target)),target);if(fragment&&target.endsWith('.md'))assert.ok(anchors(target).has(decodeURIComponent(fragment)),'Broken Markdown anchor '+path+' -> '+ref);links++;}}
 return {markdown:[...packed].filter(p=>p.endsWith('.md')).length,links};
}
export function cutover(root:string,development=false){
 const pkg=JSON.parse(readFileSync(join(root,'package.json'),'utf8'));
 const removed=['adapters','application','authorization','certification','cleanup','compatibility','component','containment','domain','driver','evaluation','fixtures','git','legacy','persistence','phase7','pr0','public','recovery','reports','retention','schemas','system','util'];
 for(const name of removed)assert.equal(existsSync(join(root,'src',name)),false,'Removed architecture: src/'+name);
 for(const name of ['certification','scripts','browser-tests','dist','.test-dist'])assert.equal(existsSync(join(root,name)),false,'No legacy/build payload: '+name);
 assert.deepEqual(files(root,'bin'),['bin/pi-fabric-arbor.mjs']);assert.deepEqual(files(root,'web'),['web/read-only/app.css','web/read-only/app.js','web/read-only/index.html']);
 const reachable=new Set<string>();function visit(path:string){path=resolve(path);assert.ok(path.startsWith(resolve(root,'src')+'/'));const name=relative(root,path);if(reachable.has(name))return;reachable.add(name);const text=readFileSync(path,'utf8');assert.doesNotMatch(text,/ArborApplication|AdmittedDriverDispatcher|FingerprintBoundaryGuard|LinuxBubblewrap|DetachedMonitor|ReleaseWebAssets|TrustedPrincipalRegistry|setpgid|cgroup|CSRF|bubblewrap/);for(const {fileName:ref} of ts.preProcessFile(text,true,true).importedFiles){if(ref.startsWith('.'))visit(resolve(dirname(path),ref.replace(/\.js$/,'.ts')));else if(ref.startsWith('pi-fabric'))assert.ok(['pi-fabric','pi-fabric/protocol'].includes(ref),'No private Fabric import '+ref);else assert.ok(!ref.startsWith('/')&&!ref.includes('.pi/'),'No profile/absolute import');}}
 for(const p of ['src/extension.ts','src/package.ts','src/cli/read-only.ts'])visit(join(root,p));assert.deepEqual(files(root,'src'),[...reachable].sort(),'No second/unreachable runtime remains');
 assert.deepEqual(pkg.exports,{'.':{types:'./src/package.ts',import:'./src/package.ts'},'./extension':{types:'./src/extension.ts',import:'./src/extension.ts'},'./assets':{types:'./src/package.ts',import:'./src/package.ts'}});assert.deepEqual(pkg.bin,{'pi-fabric-arbor':'./bin/pi-fabric-arbor.mjs'});assert.deepEqual(pkg.pi,{extensions:['./src/extension.ts'],skills:['./skills/fabric-arbor/SKILL.md']});
 assert.deepEqual(files(root,'skills').filter(p=>p.endsWith('/SKILL.md')),['skills/fabric-arbor/SKILL.md']);assert.equal(files(root,'skills').filter(p=>p.startsWith('skills/fabric-arbor/roles/')&&p.endsWith('.md')).length,3);
 for(const key of ['build','prepack','prepare','test:source:retained','test:pr0:e2e','test:pr0:plan'])assert.equal(pkg.scripts[key],undefined,key);
 for(const [name,script] of Object.entries(pkg.scripts) as [string,string][]){assert.doesNotMatch(script,/dist\/|\.test-dist|certif|phase7|src\/legacy|test:source:retained/);for(const call of script.matchAll(/npm run ([a-z0-9:-]+)/g))assert.ok(pkg.scripts[call[1]!],name+' calls missing script');if(development)for(const match of script.matchAll(/tests\/[^\s'"]+\.ts/g))assert.ok(globSync(match[0],{cwd:root}).length>0,'Missing registered test '+match[0]);}
 const manifest=JSON.parse(readFileSync(join(root,'docs/pr3-action-manifest.json'),'utf8'));assert.equal(manifest.actions.length,21);assert.deepEqual(manifest.ownerProvides,['arbor','arbor_lifetime']);assert.deepEqual(manifest.drainRequires,['arbor_lifetime.lease']);assert.deepEqual(manifest.actorRequires,['agents.self']);assert.equal(manifest.ownerRequires.length,10);assert.equal(manifest.internalCapabilities.length,1);assert.equal(manifest.internalCapabilities[0].acquisitionOnly,true);
 assert.deepEqual(manifest.ownerRequires,['agents.self','agents.members','agents.status','agents.create','agents.ask','agents.spawn','agents.wait','agents.stop','agents.remove','schema.status']);
 assert.equal(manifest.internalCapabilities[0].risk,'agent');assert.deepEqual(manifest.internalCapabilities[0].effect,{kind:'scoped',ordering:'ordered',resources:['arbor:owner:lifetime']});assert.equal(manifest.internalCapabilities[0].inputSchema.additionalProperties,false);
 assert.equal([...readFileSync(join(root,'docs/role-maintenance.md'),'utf8').matchAll(/^\| arbor-/gm)].length,11,'Every upstream skill has an explicit disposition');
 for(const name of ['code','agent','recipe'])assert.ok(files(root,'examples/'+name).length>=2,name+' runnable pack');
 return {modules:[...reachable].sort(),ordinaryRefs:21,scopedRefs:1,publicSkills:1,internalRoles:3,examples:3};
}
